import {transfersPanel,refreshTransfers} from './transfers-ui.js?v=0.21.0';
import {familyMap} from '../shared/ancestry-ui.js?v=0.21.0';
import {mountShell} from '../shared/shell.js?v=0.22.0';
import {attachCardDrag} from '../shared/drag.js?v=0.21.0';
import {escapeHtml as e, downloadText} from '../shared/utils.js?v=0.21.0';
import {KEY, SOURCES, FITS, initialState, active, targetFor, roleName, createHistory, change, undo, apply, validateState, serialize, parse, markdown} from './state.js?v=0.21.0';
mountShell({active:'analogy'});
const root=document.querySelector('#app'), dialog=document.querySelector('#dialog');
let history=createHistory(initialState()), timer, toastTimer, dragDestroy, dialogOrigin=null, dialogFocus=null, paused=false, recovery=null, saveMessage='Saved on this device';
try {const raw=localStorage.getItem(KEY); if(raw){try{history=createHistory(validateState(JSON.parse(raw)));}catch{recovery=raw;paused=true;saveMessage='Saved data needs recovery';}}}catch{saveMessage='Saving unavailable · export a copy';}
const state=()=>history.present, work=()=>active(state()), uid=()=>crypto.randomUUID?.() || `a-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const short=(value,limit=90)=>value.length>limit?`${value.slice(0,limit-1)}…`:value;
const textName=value=>value.trim() || 'Untitled';
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,4400);}
function announce(message){document.querySelector('#live').textContent=message;}
function status(){const el=document.querySelector('#save');if(el)el.textContent=saveMessage;}
function save(now=false){clearTimeout(timer);if(paused)return;saveMessage='Saving…';status();const run=()=>{try{localStorage.setItem(KEY,JSON.stringify(state()));saveMessage='Saved on this device';}catch{saveMessage='Saving unavailable · export a copy';}status();};if(now)run();else timer=setTimeout(run,250);}
function act(action,{repaint=true,group=null,checkpoint=true,focus=null}={}){
  const focused=document.activeElement,oldId=focused?.id,oldData=focused?.dataset?.action?{...focused.dataset}:null;
  try{history=checkpoint?change(history,action,group):{...history,present:apply(state(),action),group:null};save();if(repaint)render();if(focus)requestAnimationFrame(()=>document.getElementById(focus)?.focus());else if(repaint)(oldId?document.getElementById(oldId):oldData?[...root.querySelectorAll('[data-action]')].find(el=>['action','id','side','source','fit'].every(key=>el.dataset[key]===oldData[key])):null)?.focus({preventScroll:true});return true;}catch(error){toast(error.message);return false;}
}
function resize(scope=document){scope.querySelectorAll('textarea').forEach(el=>{el.style.height='auto';el.style.height=`${Math.max(el.scrollHeight,58)}px`;});}
function field(id,label,value,data,prompt='',rows=2){return `<div class="field"><label for="${e(id)}">${label}</label>${prompt?`<p id="${e(id)}-help">${e(prompt)}</p>`:''}<textarea id="${e(id)}" rows="${rows}" maxlength="20000" ${data} ${prompt?`aria-describedby="${e(id)}-help"`:''}>${e(value)}</textarea></div>`;}
function roleCard(role,mapped=false){return `<article class="target-card" data-drag-id="${e(role.id)}"><div class="target-card-top"><span>YOUR TARGET</span><button class="drag-handle" data-drag-handle data-action="map-menu" data-id="${e(role.id)}" aria-label="Match target role: ${e(roleName(role))}">⠿</button></div><h3>${e(roleName(role,'Name this role…'))}</h3><p>${role.job.trim()?e(role.job):'<span class="muted">What function does it perform?</span>'}</p><div class="target-card-actions"><button class="text-button" data-action="edit-role" data-side="target" data-id="${e(role.id)}">Edit<span class="sr-only"> ${e(roleName(role))}</span></button><button class="text-button" data-action="map-menu" data-id="${e(role.id)}">${mapped?'Rematch':'Match'} ↗</button></div></article>`;}
function mappingBoard(){
  const workspace=work(),unmapped=workspace.targets.filter(role=>!workspace.mappings.some(mapping=>mapping.targetId===role.id));
  return `<section id="mapping" class="mapping-section" aria-labelledby="mapping-title"><div class="section-top"><div><span class="eyebrow">01 / MATCH FUNCTIONS</span><h2 id="mapping-title">Different names. A similar job?</h2><p>Drag a target card beside its counterpart, or use Match. Match what it does, not what it resembles.</p></div><span class="count">${workspace.mappings.length}/${workspace.source.roles.length} roles mapped</span></div>
    <div class="mapping-layout"><div class="matching-lanes"><div class="mapping-column-labels"><span>IN THE SOURCE</span><span>IN YOUR SITUATION</span></div>${workspace.source.roles.map((role,index)=>{const target=targetFor(workspace,role.id),mapping=workspace.mappings.find(item=>item.sourceId===role.id);return `<article class="matching-row ${target?'has-match':''}" id="match-${e(role.id)}"><div class="source-role"><span class="role-number">${String(index+1).padStart(2,'0')}</span><div><h3>${e(roleName(role,'Name this source role…'))}</h3><p>${role.job.trim()?e(role.job):'<span class="muted">Describe its function in the source.</span>'}</p><button class="text-button" data-action="edit-role" data-side="source" data-id="${e(role.id)}">Edit source role</button></div></div><div class="match-connector" aria-hidden="true"><span></span>↔<span></span></div><div class="target-slot" data-drop-id="${e(role.id)}" aria-label="Match a target role to ${e(roleName(role))}">${target?`${roleCard(target,true)}<details class="match-reason"><summary>Same function because… <span>${mapping.reason.trim()?'Written':'Add your reasoning'}</span></summary>${field(`reason-${role.id}`,'Why is this a useful match?',mapping.reason,`data-edit="reason" data-source="${e(role.id)}"`,'Name the shared job. Where is the resemblance only superficial?')}</details>`:'<div class="empty-match"><span aria-hidden="true">+</span><strong>Match a target role</strong><span>Drag a card here or use its Match button.</span></div>'}</div></article>`;}).join('')}${!workspace.source.roles.length?'<div class="empty-state">Add source roles to describe the mechanism.</div>':''}<button class="text-button add-source" data-action="add-role" data-side="source" ${workspace.source.roles.length>=6?'disabled':''}>+ Add a source role</button></div>
    <aside class="target-bank" data-drop-id="unmapped" aria-label="Unmatched target roles"><div class="bank-heading"><span class="eyebrow">YOUR PARTS</span><h3>Not yet matched <span>${unmapped.length}</span></h3><p>Roles can be people, resources, rules, or signals.</p></div><div class="bank-cards">${unmapped.map(role=>roleCard(role)).join('')||'<p class="bank-empty">All target cards are matched. Drop one here to unmatch it.</p>'}</div><button class="button" data-action="add-role" data-side="target" ${workspace.targets.length>=6?'disabled':''}>+ Add target role</button><p class="bank-note">A new match replaces the old pairing. The displaced card comes back here.</p></aside></div></section>`;
}
function relationships(){
  const workspace=work(),link=workspace.source.links.find(link=>link.id===workspace.selectedLink),from=link?workspace.source.roles.find(role=>role.id===link.from):null,to=link?workspace.source.roles.find(role=>role.id===link.to):null,check=link?workspace.reviews[link.id]:null,targetFrom=link?targetFor(workspace,link.from):null,targetTo=link?targetFor(workspace,link.to):null;
  return `<section id="relationships" class="relationship-section" aria-labelledby="relationships-title"><div class="section-top"><div><span class="eyebrow">02 / TEST THE RELATIONSHIPS</span><h2 id="relationships-title">The mechanism lives in the links.</h2><p>Matching the parts is only the start. Does one thing cause, enable, or constrain another in the same way?</p></div><button class="button" data-action="add-link" ${workspace.source.links.length>=10||!workspace.source.roles.length?'disabled':''}>+ Relationship</button></div><div class="relationship-layout"><div class="relationship-list" aria-label="Source relationships">${workspace.source.links.map(item=>{const itemCheck=workspace.reviews[item.id],mapped=targetFor(workspace,item.from)&&targetFor(workspace,item.to);return `<button class="relationship-choice ${item.id===workspace.selectedLink?'active':''}" data-action="select-link" data-id="${e(item.id)}" aria-pressed="${item.id===workspace.selectedLink}"><span class="relationship-route">${e(roleName(workspace.source.roles.find(role=>role.id===item.from)))} <span aria-hidden="true">→</span> ${e(roleName(workspace.source.roles.find(role=>role.id===item.to)))}</span><strong>${e(item.label||'Name this relationship…')}</strong><span class="fit-tag fit-${itemCheck.fit}">${!mapped?'Needs both roles':itemCheck.stale?'Mapping changed · recheck':FITS[itemCheck.fit]}</span></button>`;}).join('')||'<p class="empty-state">Add a relationship to explain how the source roles affect each other.</p>'}</div>
    <div class="relationship-inspector">${link?`<div class="inspector-top"><span class="eyebrow">ONE RELATIONSHIP, TWO CONTEXTS</span><button class="text-button" data-action="edit-link" data-id="${e(link.id)}">Edit relationship</button></div><div class="relationship-pair"><span class="pair-label">SOURCE</span><div class="pair-route"><strong>${e(roleName(from))}</strong><span aria-hidden="true">→</span><strong>${e(roleName(to))}</strong></div><p>${e(link.label||'Describe the relationship.')}</p></div><div class="relationship-pair target-pair"><span class="pair-label">YOUR TARGET</span><div class="pair-route"><strong class="${targetFrom?'':'missing-role'}">${e(roleName(targetFrom,'Not matched'))}</strong><span aria-hidden="true">→</span><strong class="${targetTo?'':'missing-role'}">${e(roleName(targetTo,'Not matched'))}</strong></div><p>Does “${e(link.label||'this relationship')}” still describe what happens?</p></div><div id="relationship-stale">${check.stale?'<p class="stale-note">The mapping or source changed. Your earlier note is kept; check the relationship again.</p>':''}</div>${field('relationship-target','What actually happens in the target?',check.targetRelation,`data-edit="review" data-id="${e(link.id)}" data-field="targetRelation"`,'Write the target interaction in its own terms.')}<fieldset class="fit-controls"><legend>How well does this relationship transfer?</legend>${[['fits','Holds'],['partial','Partly'],['breaks','Breaks']].map(([key,label])=>`<button class="fit-button ${check.fit===key?'selected':''} fit-${key}" data-action="fit" data-id="${e(link.id)}" data-fit="${key}" aria-pressed="${check.fit===key}" ${!targetFrom||!targetTo?'disabled':''}>${label}</button>`).join('')}<button class="text-button" data-action="fit" data-id="${e(link.id)}" data-fit="unchecked">Clear judgment</button></fieldset>${!targetFrom||!targetTo?'<p class="missing-note">Match both endpoint roles before judging this relationship.</p>':''}${field('relationship-note','The condition, mismatch, or missing link',check.note,`data-edit="review" data-id="${e(link.id)}" data-field="note"`,'What behaves differently? Keep earlier reasoning here.',3)}<details id="relationship-conditions"><summary>Conditions and failure points</summary>${field('relationship-condition','What has to be true for this to work?',check.condition,`data-edit="review" data-id="${e(link.id)}" data-field="condition"`,'Name the enabling condition, resource or response.')}${field('relationship-failure','When would it stop helping?',check.failure,`data-edit="review" data-id="${e(link.id)}" data-field="failure"`,'A concrete situation where the borrowed link fails or causes harm.')}</details>}`:'<div class="empty-state"><h3>Describe an interaction.</h3><p>Connect two source roles with a verb: allocates, limits, releases, observes, or changes.</p></div>'}</div></div></section>`;
}
function adaptation(){
  const workspace=work(),breaks=workspace.source.links.filter(link=>['breaks','partial'].includes(workspace.reviews[link.id].fit));
  return `<section id="adaptation" class="adaptation-section" aria-labelledby="adaptation-title"><div class="section-top"><div><span class="eyebrow">03 / ADAPT & TEST</span><h2 id="adaptation-title">Borrow the mechanism. Redesign the details.</h2><p>A useful analogy leads to a test, not a claim that the two situations are the same.</p></div><button class="button" data-action="export">Export work ↓</button></div><button class="button primary capture-option" data-action="option-capture">Develop an adaptation from this draft →</button><details class="original-plan" id="original-plan" ${workspace.options.length?'':'open'}><summary>Source draft and current mismatches</summary><div class="adaptation-layout"><aside class="boundaries"><span class="eyebrow">WHERE THE SOURCE STOPS HELPING</span><h3>The broken analogy is useful too.</h3>${breaks.length?breaks.map(link=>`<button class="boundary-note" data-action="go-link" data-id="${e(link.id)}"><span class="fit-tag fit-${workspace.reviews[link.id].fit}">${FITS[workspace.reviews[link.id].fit]}</span><strong>${e(link.label||'Unnamed relationship')}</strong><span>${workspace.reviews[link.id].note.trim()?e(workspace.reviews[link.id].note):'Write what differs in the relationship check.'}</span></button>`).join(''):'<p>No mismatches recorded yet. Which assumption in the source is least likely to hold here?</p>'}<p class="boundary-foot">A missing counterpart or failed relationship can be a design requirement, not a reason to force the match.</p></aside><div class="plan-editor"><div class="plan-field-top"><span class="eyebrow">YOUR ADAPTATION</span><button class="text-button" data-action="copy-mechanism">Copy source mechanism ↘</button></div>${field('plan-mechanism','The mechanism worth keeping',workspace.plan.mechanism,'data-edit="plan" data-field="mechanism"','State the working principle without relying on the metaphor.',3)}${field('plan-adaptation','The change I would make here',workspace.plan.adaptation,'data-edit="plan" data-field="adaptation"','Which role, rule, signal, or interaction will change?')}${field('plan-boundary','What needs redesigning',workspace.plan.boundary,'data-edit="plan" data-field="boundary"','Use the broken relationships. What cannot be copied?')}<div class="test-fields">${field('plan-test','The smallest useful test',workspace.plan.test,'data-edit="plan" data-field="test"','Who will try what, for how long, and with which limit on effort?')}${field('plan-learn','What would change my mind?',workspace.plan.learn,'data-edit="plan" data-field="learn"','If I observe ___, I will revise, stop, or continue by ___.')}</div></div></div></details>${transfersPanel(workspace)}</section>`;
}
function render(){
  const opened=[...root.querySelectorAll('details[open][id]')].map(el=>el.id),scroll=root.querySelector('.options-scroll')?.scrollLeft||0;
  dragDestroy?.();const workspace=work();
  root.innerHTML=`<header class="page-top"><div><p class="eyebrow">SCAFFOLD 04 / TRANSFER A MECHANISM</p><h1>Analogy workshop</h1></div><div class="toolbar"><button class="button quiet" data-action="undo" ${history.past.length?'':'disabled'}>↶ Undo</button><button class="button" data-action="workspaces">My work <span>${state().workspaces.length}</span></button><button class="button" data-action="export">Export ↓</button></div></header>${paused?`<div class="notice">${recovery?'Saved work could not be opened. Download a recovery copy before replacing it.':'Another tab changed the saved work. Saving here is paused; export this version or explicitly keep it.'}<button class="text-button" data-action="${recovery?'recover':'resume'}">${recovery?'Download recovery copy':'Save this tab instead'}</button></div>`:''}
    <section class="problem-bar"><div class="problem-meta"><label for="problem">Your target situation</label><span id="save" role="status">${e(saveMessage)}</span></div><textarea id="problem" data-edit="problem" rows="1" maxlength="20000" placeholder="How could we…?">${e(workspace.problem)}</textarea></section><section class="source-strip"><div class="source-identity"><span class="source-mark" aria-hidden="true">↔</span><div><span class="eyebrow">BORROWING FROM</span><h2>${e(textName(workspace.source.name))}</h2></div></div><p>${workspace.source.principle.trim()?e(workspace.source.principle):'Describe the working principle of your source mechanism.'}</p><div class="source-actions"><button class="text-button" data-action="edit-source">Edit source</button><button class="text-button" data-action="sources">Try another mechanism ↗</button></div></section><nav class="step-nav" aria-label="Workshop sections"><a href="#mapping"><span>01</span> Match functions</a><a href="#relationships"><span>02</span> Test relationships</a><a href="#adaptation"><span>03</span> Adapt & test</a></nav>
    ${mappingBoard()}${relationships()}${adaptation()}<footer class="local-footer"><p>Simplified source mechanisms and fictional targets. Your mapping is a hypothesis.</p><p>Saved in this browser. Export a portable copy.</p></footer>`;
  opened.forEach(id=>document.getElementById(id)?.setAttribute('open',''));
  if(root.querySelector('.options-scroll'))root.querySelector('.options-scroll').scrollLeft=scroll;
  requestAnimationFrame(()=>resize(root));
  dragDestroy=attachCardDrag({root,onDrop:({itemId,dropId})=>mapRole(itemId,dropId==='unmapped'?null:dropId)});
}
function mapRole(targetId,sourceId){if(act({type:'map',targetId,sourceId})){const role=work().targets.find(role=>role.id===targetId),source=work().source.roles.find(role=>role.id===sourceId);const message=source?`${roleName(role)} matched to ${roleName(source)}. Check the relationships that changed.`:`${roleName(role)} returned to unmatched roles.`;toast(message);announce(message);if(sourceId){const row=document.getElementById(`match-${sourceId}`);row?.classList.add('just-matched');setTimeout(()=>row?.classList.remove('just-matched'),1100);}}}
function open(content,title){dialogFocus=null;dialogOrigin=document.activeElement?.dataset?.action?{...document.activeElement.dataset}:null;dialog.innerHTML=`<div class="dialog-top"><h2 id="dialog-title">${title}</h2><button class="close" data-action="close" aria-label="Close dialog">×</button></div>${content}`;dialog.setAttribute('aria-labelledby','dialog-title');dialog.showModal();requestAnimationFrame(()=>resize(dialog));}
function openRole(side,id){const role=(side==='source'?work().source.roles:work().targets).find(role=>role.id===id);open(`${field('edit-role-label','Role name',role.label,`data-edit="role" data-side="${side}" data-id="${e(id)}" data-field="label"`,'A person, resource, rule, or signal.')}${field('edit-role-job','What function does it perform?',role.job,`data-edit="role" data-side="${side}" data-id="${e(id)}" data-field="job"`,'Describe what it does and what depends on it.',3)}<div class="dialog-footer"><button class="text-button danger" data-action="remove-role" data-side="${side}" data-id="${e(id)}">Remove this role</button><button class="button primary" data-action="close">Done</button></div><p class="microcopy">Changing a function marks affected relationship checks for review. Undo restores removed roles and their links.</p>`,side==='source'?'Edit a source role':'Edit a target role');}
function openLink(id){const link=work().source.links.find(link=>link.id===id);const endpoint=(key,label)=>`<div class="field"><label for="link-${key}">${label}</label><select id="link-${key}" data-edit="link" data-id="${e(id)}" data-field="${key}">${work().source.roles.map(role=>`<option value="${e(role.id)}" ${role.id===link[key]?'selected':''}>${e(roleName(role))}</option>`).join('')}</select></div>`;open(`${endpoint('from','From this source role')}${field('edit-link-label','What does it do to the other role?',link.label,`data-edit="link" data-id="${e(id)}" data-field="label"`,'Use a verb: allocates, limits, releases, observes, or changes.')}${endpoint('to','To this source role')}<div class="dialog-footer"><button class="text-button danger" data-action="remove-link" data-id="${e(id)}">Remove relationship</button><button class="button primary" data-action="close">Done</button></div>`,'Edit a relationship');}
function openSources(){open('<p class="dialog-description">Try another source with the same target roles. Saved adaptations come with you. Your original mapping and draft stay in the previous workspace.</p><div class="source-options">'+Object.entries(SOURCES).map(([key,source])=>`<button data-action="fork-source" data-source="${key}"><strong>${source.name}</strong><span>${source.summary}</span></button>`).join('')+'</div>','Choose a source mechanism');}
function openWorkspaces(){open(`<p class="dialog-description">Starting a new workshop keeps your current work.</p><div class="new-options"><button class="button primary" data-action="new" data-source="library" data-blank="true">+ My own target</button><button class="button" data-action="new" data-source="custom" data-blank="true">My own source & target</button></div><details class="example-options"><summary>Open a fictional example</summary><div>${Object.entries(SOURCES).filter(([key])=>key!=='custom').map(([key,source])=>`<button class="button" data-action="new" data-source="${key}">${source.name}</button>`).join('')}</div></details><div class="workspace-list">${[...state().workspaces].reverse().map(workspace=>`<button data-action="switch" data-id="${e(workspace.id)}"><span><strong>${e(short(workspace.problem.trim()||'Untitled target'))}</strong><small>${e(workspace.source.name)} · ${workspace.mappings.length} matches</small></span><span>${workspace.id===state().activeId?'Open':'→'}</span></button>`).join('')}</div><button class="text-button" data-action="import">Import an editable JSON workshop ↑</button>`,'My workshops');}
function openMap(id){const target=work().targets.find(role=>role.id===id),mapping=work().mappings.find(mapping=>mapping.targetId===id);open(`<p class="moving-name">${e(roleName(target))}</p><p class="dialog-description">Which source role performs a similar function?</p><div class="map-options">${work().source.roles.map(role=>{const other=targetFor(work(),role.id);return `<button data-action="map" data-id="${e(id)}" data-source="${e(role.id)}" ${mapping?.sourceId===role.id?'disabled':''}><strong>${e(roleName(role))}</strong><span>${e(role.job||'Function not described yet.')}</span>${other&&other.id!==id?`<small>Replaces ${e(roleName(other))}; that card returns to the bank.</small>`:''}</button>`;}).join('')}${mapping?`<button data-action="unmap" data-id="${e(id)}"><strong>Return to unmatched roles</strong><span>Keep this role without forcing a counterpart.</span></button>`:''}</div>`,'Match a function');}
document.addEventListener('click',event=>{
  const button=event.target.closest('[data-action]');if(!button)return;const {action,id,side,source,fit}=button.dataset;
  if(action==='option-family')open(familyMap(work().options,{action:'option-select'}),'Adaptation branches');
  else if(action.startsWith('option-')){const opens=['option-capture','option-branch','option-recast','option-select'].includes(action);if(dialog.open){dialogFocus=opens?'option-title':null;dialog.close();}
    if(act({type:action,id,newId:uid()},{checkpoint:action!=='option-select',focus:opens?'option-title':null})){if(opens)document.getElementById('option-editor')?.scrollIntoView({block:'start'});}
    else if(action==='option-compare')button.checked=work().compareOptions.includes(id);
  }
  else if(action==='undo'){history=undo(history);save();render();toast('Last change undone.');}
  else if(action==='close')dialog.close();
  else if(action==='workspaces')openWorkspaces();
  else if(action==='sources')openSources();
  else if(action==='new'){dialog.close();if(act({type:'new',id:uid(),source,blank:button.dataset.blank==='true'},{focus:'problem'}))toast('New workshop opened. Previous work is in My work.');}
  else if(action==='fork-source'){dialog.close();if(act({type:'fork-source',id:uid(),source}))toast('New source opened with your target preserved. The previous workshop is saved.');}
  else if(action==='switch'){dialog.close();act({type:'switch',id},{checkpoint:false});}
  else if(action==='edit-role')openRole(side,id);
  else if(action==='add-role'){const id=uid();if(act({type:'add-role',id,side}))openRole(side,id);}
  else if(action==='remove-role'){dialog.close();if(act({type:'remove-role',id,side}))toast('Role removed with its dependent mappings and links. Undo restores them.');}
  else if(action==='map-menu')openMap(id);
  else if(action==='map'||action==='unmap'){dialog.close();mapRole(id,action==='unmap'?null:source);}
  else if(action==='select-link')act({type:'select-link',id},{checkpoint:false});
  else if(action==='go-link'){act({type:'select-link',id},{checkpoint:false});document.querySelector('#relationships').scrollIntoView({behavior:'smooth',block:'start'});}
  else if(action==='fit'){act({type:'review',id,field:'fit',value:fit});announce(`Relationship marked: ${FITS[fit]}.`);}
  else if(action==='edit-link')openLink(id);
  else if(action==='add-link'){const id=uid();if(act({type:'add-link',id}))openLink(id);}
  else if(action==='remove-link'){dialog.close();if(act({type:'remove-link',id}))toast('Relationship removed. Undo restores it and its check.');}
  else if(action==='edit-source')open(`${field('source-name','Source name',work().source.name,'data-edit="source" data-field="name"')}${field('source-principle','How does the mechanism work?',work().source.principle,'data-edit="source" data-field="principle"','Explain the sequence or causal relationship, without relying on a slogan.',4)}<div class="dialog-footer"><p class="microcopy">Edit individual roles and relationships on the canvas.</p><button class="button primary" data-action="close">Done</button></div>`,'Edit the source mechanism');
  else if(action==='copy-mechanism'){if(act({type:'copy-mechanism'}))toast('Source principle copied into your draft. Undo restores the previous wording.');}
  else if(action==='export')open('<p class="dialog-description">Includes roles, mappings, relationship checks, all adaptations, their source records and the chosen test.</p><div class="export-options"><button class="button primary" data-action="markdown">Download Markdown ↓</button><button class="button" data-action="json">Download editable JSON ↓</button></div><p class="microcopy">Export a portable copy before clearing browser data.</p>','Export this workshop');
  else if(action==='markdown'||action==='json'){downloadText(`analogy-workshop.${action==='json'?'json':'md'}`,action==='json'?serialize(work()):markdown(work()),action==='json'?'application/json':'text/markdown;charset=utf-8');dialog.close();toast('Workshop downloaded.');}
  else if(action==='import')document.querySelector('#file').click();
  else if(action==='recover'){downloadText('analogy-recovery.json',recovery,'application/json');recovery=null;paused=false;save();render();}
  else if(action==='resume'){paused=false;save();render();}
});
document.addEventListener('input',event=>{
  const el=event.target;if(!(el instanceof HTMLTextAreaElement)||!el.dataset.edit)return;const {edit,id,field,side,source,linkId}=el.dataset;
  const action=edit==='problem'?{type:'problem',value:el.value}:edit==='reason'?{type:'reason',sourceId:source,value:el.value}:{type:edit,id,field,side,linkId,value:el.value};
  if(act(action,{repaint:false,group:el.id})){el.style.height='auto';el.style.height=`${Math.max(el.scrollHeight,58)}px`;root.querySelector('[data-action="undo"]').disabled=false;refreshTransfers(root,work());
    refreshReviewSignals();
  }
});
document.addEventListener('change',event=>{const el=event.target;if(el instanceof HTMLSelectElement&&el.dataset.edit==='option-response'){if(act({type:'option-response',id:el.dataset.id,linkId:el.dataset.linkId,field:el.dataset.field,value:el.value},{repaint:false})){root.querySelector('[data-action="undo"]').disabled=false;refreshTransfers(root,work());}}
 else if(el instanceof HTMLSelectElement&&el.dataset.edit==='link')act({type:'link',id:el.dataset.id,field:el.dataset.field,value:el.value},{repaint:false});});
document.addEventListener('focusout',()=>{history.group=null;});
root.addEventListener('toggle',event=>{if(event.target instanceof HTMLDetailsElement&&event.target.open)requestAnimationFrame(()=>resize(event.target));},true);
dialog.addEventListener('close',()=>{render();if(dialogFocus){document.getElementById(dialogFocus)?.focus({preventScroll:true});dialogFocus=null;}else if(dialogOrigin)[...root.querySelectorAll('[data-action]')].find(el=>['action','id','side','source'].every(key=>el.dataset[key]===dialogOrigin[key]))?.focus({preventScroll:true});dialogOrigin=null;});
dialog.addEventListener('click',event=>{if(event.target===dialog){const box=dialog.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)dialog.close();}});
document.querySelector('#file').addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file)return;try{if(file.size>7000000)throw new Error('Choose a JSON file under 7 MB.');const imported=parse(await file.text());dialog.close();if(act({type:'import',id:uid(),workspace:imported}))toast('Workshop imported. Existing work is preserved.');}catch(error){toast(error.message);}event.target.value='';});
window.addEventListener('pagehide',()=>save(true));window.addEventListener('storage',event=>{if(event.key!==KEY||event.newValue===JSON.stringify(state()))return;clearTimeout(timer);paused=true;saveMessage='Local saving paused';render();});
render();if(!paused)save();

function refreshReviewSignals(){
 const w=work(),selected=w.reviews[w.selectedLink];
 for(const link of w.source.links){const r=w.reviews[link.id],mapped=targetFor(w,link.from)&&targetFor(w,link.to),button=[...root.querySelectorAll('.relationship-choice')].find(el=>el.dataset.id===link.id),tag=button?.querySelector('.fit-tag');if(tag){tag.className='fit-tag fit-'+r.fit;tag.textContent=!mapped?'Needs both roles':r.stale?'Mapping changed · recheck':FITS[r.fit];}}
 if(selected){root.querySelectorAll('.fit-controls [data-fit]').forEach(b=>{b.classList.toggle('selected',b.dataset.fit===selected.fit);b.setAttribute('aria-pressed',String(b.dataset.fit===selected.fit));});const stale=root.querySelector('#relationship-stale');if(stale)stale.innerHTML=selected.stale?'<p class="stale-note">The mapping or source changed. Your earlier note is kept; check the relationship again.</p>':'';}
}
